   var city=GameObject.Find("Lower Castle City");if(!city)throw new InvalidOperationException("Lower city missing.");if(GameObject.Find("Synty Walking City Population"))return;var roads=city.transform.Find("Winding Roads and Market Square");if(!roads)throw new InvalidOperationException("City roads missing.");
   var walk=Clip("Assets/Starter Assets/Runtime/ThirdPersonController/Character/Animations/Locomotion--Walk_N.anim.fbx");var idle=Clip("Assets/Starter Assets/Runtime/ThirdPersonController/Character/Animations/Stand--Idle.anim.fbx");if(!walk.isHumanMotion||!idle.isHumanMotion)throw new InvalidOperationException("Idle/walk clips must support Humanoid retargeting.");
   string folder="Assets/CityExpansion/SyntyNpcPopulation";Directory.CreateDirectory(folder);AssetDatabase.Refresh();var controller=AnimatorController.CreateAnimatorControllerAtPath(folder+"/CityWalkIdle.controller");controller.AddParameter("Speed",AnimatorControllerParameterType.Float);var state=controller.layers[0].stateMachine.AddState("Idle And Walk");var blend=new BlendTree{name="City Idle Walk",blendType=BlendTreeType.Simple1D,blendParameter="Speed",useAutomaticThresholds=false};blend.AddChild(idle,0);blend.AddChild(walk,1.4f);AssetDatabase.AddObjectToAsset(blend,controller);state.motion=blend;controller.layers[0].stateMachine.defaultState=state;
   var scene=SceneManager.GetActiveScene();string backup="Assets/ForestExpansion/Backups/MyForest-before-synty-npc-population-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity";if(!EditorSceneManager.SaveScene(scene,backup,true))throw new IOException("Scene backup failed.");
   var original=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var matrices=original.Select(t=>t.localToWorldMatrix).ToArray();var converted=new Dictionary<Material,Material>();var prefabs=new List<GameObject>();int removed=0,renderers=0;float walkMotion=0;
   foreach(int id in new[]{1,10,20,40,60,80})
