    var nodes=new List<Vector3>();foreach(var filter in roads.GetComponentsInChildren<MeshFilter>()){if(filter.name=="Central Market Square")continue;var v=filter.sharedMesh.vertices;for(int i=0;i+1<v.Length;i+=12){var p=filter.transform.TransformPoint((v[i]+v[i+1])*.5f);if(NavMesh.SamplePosition(p,out NavMeshHit hit,1.5f,1)&&nodes.All(n=>Vector3.Distance(n,hit.position)>4))nodes.Add(hit.position);}}
    if(nodes.Count<16)throw new InvalidOperationException("Fewer than 16 usable road positions; NPC population not installed.");var components=new List<List<Vector3>>();var unused=new HashSet<Vector3>(nodes);while(unused.Count>0){var seed=unused.First();var set=new List<Vector3>();foreach(var point in unused.ToArray()){var path=new NavMeshPath();if(NavMesh.CalculatePath(seed,point,1,path)&&path.status==NavMeshPathStatus.PathComplete){set.Add(point);unused.Remove(point);}}if(set.Count==0){unused.Remove(seed);continue;}components.Add(set);}var connected=components.OrderByDescending(c=>c.Count).First();if(connected.Count<16)throw new InvalidOperationException("Road network cannot support 16 connected spawn sites.");
    var root=new GameObject("Synty Walking City Population");Undo.RegisterCreatedObjectUndo(root,"Add moderate Synty NPC population");var registry=root.AddComponent<CityPopulationNavigation>();registry.Data=data;var spawnPoints=new List<Vector3>();foreach(var point in connected){if(spawnPoints.All(p=>Vector3.Distance(p,point)>7))spawnPoints.Add(point);if(spawnPoints.Count==16)break;}if(spawnPoints.Count<16)throw new InvalidOperationException("Insufficient separated spawn points.");
    for(int i=0;i<16;i++){var npc=new GameObject("Walking City NPC "+(i+1).ToString("00"));npc.transform.SetParent(root.transform,false);npc.transform.position=spawnPoints[i];var visual=(GameObject)PrefabUtility.InstantiatePrefab(prefabs[i%prefabs.Count]);visual.transform.SetParent(npc.transform,false);var agent=npc.AddComponent<NavMeshAgent>();agent.agentTypeID=settings.agentTypeID;agent.radius=.30f;agent.height=1.8f;agent.baseOffset=0;agent.speed=1.15f+(i%4)*.1f;agent.acceleration=3;agent.angularSpeed=180;agent.stoppingDistance=.25f;agent.areaMask=1;agent.autoBraking=true;agent.obstacleAvoidanceType=ObstacleAvoidanceType.HighQualityObstacleAvoidance;agent.avoidancePriority=30+i;var capsule=npc.AddComponent<CapsuleCollider>();capsule.center=new Vector3(0,.875f,0);capsule.height=1.75f;capsule.radius=.28f;var walker=npc.AddComponent<CityNpcWalker>();walker.Waypoints=connected.ToArray();}
    for(int i=0;i<original.Length;i++)if(original[i].localToWorldMatrix!=matrices[i])throw new InvalidOperationException("Existing model moved; population rolled back.");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new IOException("Scene save failed.");Directory.CreateDirectory("Logs");File.WriteAllText("Logs/TestSyntyCityPopulation-report.txt","Installed 16 walking-only NPCs using six Synty presets from supplied pack only, at 1.75m height. Valid Humanoid avatars verified for all six. Editor walking retarget test passed: left-leg rotation changed "+walkMotion.ToString("F2")+" degrees between sampled walking frames. Removed "+removed+" inactive modular objects across optimized skins; retained "+renderers+" active skinned renderers. Converted palette materials to URP. Baked navigation on existing city roads with building/fence obstacles; verified "+connected.Count+" connected route points and 16 spawns at least 7m apart. Runtime wandering, idle pauses and agent avoidance configured; no combat scripts or other character packs used. Existing city/castle models retained. Live Play-mode walking still needs observation.\nBackup: "+backup);Debug.Log("Synty Humanoid walking sample passed; moderate 16-NPC population added. Enter Play mode to observe city wandering.");
   }
   finally{if(temporary.valid)temporary.Remove();}
  }
  static int Depth(Transform t){int n=0;while(t.parent){n++;t=t.parent;}return n;}
  static AnimationClip Clip(string path){var clip=AssetDatabase.LoadAllAssetsAtPath(path).OfType<AnimationClip>().FirstOrDefault(c=>!c.name.StartsWith("__preview__"));if(!clip)throw new InvalidOperationException("Animation missing: "+path);return clip;}
  static Bounds BoundsOf(GameObject go){var r=go.GetComponentsInChildren<Renderer>();if(r.Length==0)throw new InvalidOperationException("No active character geometry.");var b=r[0].bounds;foreach(var part in r)b.Encapsulate(part.bounds);return b;}
